fn two_sum(nums: &Vec<u32>, target: u32) -> (usize, usize) {
    let n = nums.len();
    for p in 0..n {
        for q in p + 1..n {
            if nums[p] + nums[q] == target {
                return (p, q);
            }
        }
    }
    // Under the problem assumptions, we will always find a solution,
    // so this point is logically unreachable.
    unreachable!("No valid two‐sum pair found");
}

